    "starterCode": "class RetailItem {\n    private String itemName;\n    private double price;\n\n    public RetailItem(String itemName, double price) {\n        this.itemName = itemName; this.price = price;\n    }\n\n    public String getItemName() {\n        return this.itemName;\n    }\n\n    public double getPrice() {\n        return this.price;\n    }\n}\n\nclass DiscountItem extends RetailItem {\n    private double discountPercent;\n\n    public DiscountItem(String itemName, double price) {\n        this(itemName, price, 5.0);\n    }\n\n    public DiscountItem(String itemName, double price, double discountPercent) {\n        super(itemName, price);\n        this.discountPercent = discountPercent;\n    }\n\n    public double getDiscountPercent() {\n        return this.discountPercent;\n    }\n}\n\nclass Main {\n    public static void main(String[] args) {\n        DiscountItem di1 = new DiscountItem(\"Shokolad\", 20000.0);\nDiscountItem di2 = new DiscountItem(\"Qahva\", 50000.0, 15.0);\nSystem.out.println(di1.getItemName() + \" [\" + di1.getDiscountPercent() + \"%] | \" + di2.getItemName() + \" [\" + di2.getDiscountPercent() + \"%]\");\n    }\n}",
    "solution": "class RetailItem {\n    private String itemName;\n    private double price;\n\n    public RetailItem(String itemName, double price) {\n        this.itemName = itemName; this.price = price;\n    }\n\n    public String getItemName() {\n        return this.itemName;\n    }\n\n    public double getPrice() {\n        return this.price;\n    }\n}\n\nclass DiscountItem extends RetailItem {\n    private double discountPercent;\n\n    public DiscountItem(String itemName, double price) {\n        this(itemName, price, 5.0);\n    }\n\n    public DiscountItem(String itemName, double price, double discountPercent) {\n        super(itemName, price);\n        this.discountPercent = discountPercent;\n    }\n\n    public double getDiscountPercent() {\n        return this.discountPercent;\n    }\n}\n\nclass Main {\n    public static void main(String[] args) {\n        DiscountItem di1 = new DiscountItem(\"Shokolad\", 20000.0);\nDiscountItem di2 = new DiscountItem(\"Qahva\", 50000.0, 15.0);\nSystem.out.println(di1.getItemName() + \" [\" + di1.getDiscountPercent() + \"%] | \" + di2.getItemName() + \" [\" + di2.getDiscountPercent() + \"%]\");\n    }\n}",
